    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i in range(len(inputs)):
        if inputs[i] != outputs[i]:
            changed.append((i, inputs[i], outputs[i]))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit operation between two strings."""
    # Find first position where they differ
    min_len = min(len(s_in), len(s_out))
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Check if insertion/deletion or substitution
            if len(s_in) < len(s_out):
                # Insertion case
                return (s_in[i], s_out[i], i)
            elif len(s_in) > len(s_out):
                # Deletion case  
                return (s_in[i], '', i)
            else:
                # Substitution case
                return (s_in[i], s_out[i], i)

    # If we reach here, one string is prefix of the other
    if len(s_in) < len(s_out):
        # Insertion at end
        return (s_in[-1] if s_in else '', s_out[len(s_in)], len(s_in))
    elif len(s_in) > len(s_out):
        # Deletion at end
        return (s_in[len(s_out)], '', len(s_out))
    else:
        # Strings are identical (shouldn't happen with our changed pairs)
        return ('', '', -1)

